import{_ as a,o,c as t,ag as i}from"./chunks/framework.cyF4XceO.js";const u=JSON.parse('{"title":"ContainerRevision — takoform_container_revision","description":"","frontmatter":{},"headers":[],"relativePath":"proposals/container/container-revision.md","filePath":"proposals/container/container-revision.md"}'),r={name:"proposals/container/container-revision.md"};function n(s,e,c,d,l,h){return o(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="containerrevision-—-takoform-container-revision" tabindex="-1">ContainerRevision — <code>takoform_container_revision</code> <a class="header-anchor" href="#containerrevision-—-takoform-container-revision" aria-label="Permalink to &quot;ContainerRevision — `takoform_container_revision`&quot;">​</a></h1><h2 id="workload-and-consumer" tabindex="-1">Workload and consumer <a class="header-anchor" href="#workload-and-consumer" aria-label="Permalink to &quot;Workload and consumer&quot;">​</a></h2><p>A team ships one immutable revision of a container service: which image runs, how its process starts, its environment, its sealed slots, and the resource and scaling bounds it serves under. Traffic selects among revisions; nothing ever edits a revision in place.</p><h2 id="role" tabindex="-1">Role <a class="header-anchor" href="#role" aria-label="Permalink to &quot;Role&quot;">​</a></h2><p><code>revision</code>. Every field is immutable; a change is a new Container Revision.</p><h2 id="observable-semantics" tabindex="-1">Observable semantics <a class="header-anchor" href="#observable-semantics" aria-label="Permalink to &quot;Observable semantics&quot;">​</a></h2><p><code>image</code> is one OCI image reference and MUST be digest-pinned (<code>name@sha256:…</code>). A mutable tag is refused with <code>invalid_argument</code> before any mutation: the digest is the revision&#39;s content identity, in the spirit of decision 0005&#39;s content-addressed locators, and a tag would let the same desired document mean different bytes on different days. The repository part of the reference says where the bytes resolve; registry choice, mirroring, and pull authorization are host and operator obligations that never enter portable state. A multi-platform index digest resolves, on each host, to a platform that host can run.</p><p><code>command</code> and <code>args</code> override the image&#39;s entrypoint and default arguments; absent, the image&#39;s own configuration applies, and absence is semantic rather than a default the host fills in. <code>vars</code> is a bounded data-only JSON map projected as environment members. <code>requiredSensitiveVars</code> declares only the names of sealed values the host must supply, under the same permitted vocabulary the Edge family records (the Form Package data-only policy forbids the token <code>secret</code> in field names).</p><p><code>externalServices</code> is carried from birth (<a href="./../../spec/decisions/0045-external-standard-services-are-sealed-slots.html">decision 0045</a>, <a href="./../../spec/standard-services/">spec/standard-services</a>): each entry is exactly <code>{&quot;name&quot;: &quot;DB&quot;, &quot;service&quot;: {&quot;apiVersion&quot;: &quot;standards.takoform.com/v1alpha1&quot;, &quot;protocol&quot;: &quot;postgresql&quot;}}</code>, with the closed protocol vocabulary <code>s3-compatible</code>, <code>postgresql</code>, <code>redis</code>, <code>smtp</code>. The host satisfies a slot with connection material; endpoints and credentials never enter portable state. The revision projects vars, sensitive names, and slot projections into ONE process environment, and because slot projections are derived member names (<code>DB_URL</code>, <code>MEDIA_ENDPOINT</code>, …), uniqueness is enforced over the PROJECTED names, not only the declared union; a host refuses the collision before mutation.</p><p><code>resources</code> fixes <code>memoryMiB</code>, the bound of usable memory — exceeding it fails the instance observably — and <code>cpu</code>, the compute allocation one instance receives in vCPU. <code>concurrencyTarget</code> is the maximum concurrent requests one instance receives; the host adds instances to hold it. <code>minInstances</code> and <code>maxInstances</code> bound the instance count while the active traffic resource weights this revision: a minimum of zero permits scale-to-zero, a positive minimum holds warm capacity, and at the maximum under saturation requests wait no longer than <code>timeoutSeconds</code> — the request&#39;s wall-clock budget — and then fail observably. All of these change what an application and its callers observe and are therefore desired state; the admitted ranges are Host Support Profile facts.</p><h2 id="why-this-is-one-form" tabindex="-1">Why this is one Form <a class="header-anchor" href="#why-this-is-one-form" aria-label="Permalink to &quot;Why this is one Form&quot;">​</a></h2><p>Image, process invocation, environment, sealed slots, and serving bounds must travel as one immutable unit, or rollback cannot be exact: re-weighting to an old revision must restore exactly the behavior it was verified with.</p><h2 id="what-would-require-a-separate-form" tabindex="-1">What would require a separate Form <a class="header-anchor" href="#what-would-require-a-separate-form" aria-label="Permalink to &quot;What would require a separate Form&quot;">​</a></h2><p>Mutable in-place configuration or a per-environment overlay breaks the immutable-revision shape. A source tree the host builds into an image changes the trust model and is a separate Form. A run-to-completion job is a different lifecycle.</p><h2 id="provided-interfaces" tabindex="-1">Provided Interfaces <a class="header-anchor" href="#provided-interfaces" aria-label="Permalink to &quot;Provided Interfaces&quot;">​</a></h2><p>None. The runtime contract belongs to the <a href="./container-service.html">ContainerService</a> identity.</p><h2 id="accepted-bindings" tabindex="-1">Accepted Bindings <a class="header-anchor" href="#accepted-bindings" aria-label="Permalink to &quot;Accepted Bindings&quot;">​</a></h2><p>None in the MVP, and the absence is honest rather than an oversight. A typed binding today projects a JavaScript surface into <code>worker.runtime</code>&#39;s environment; an arbitrary OCI process has no such namespace to project into, so realizing <code>edge.kv</code> or <code>edge.sql</code> inside a container requires a wire-level realization of the Interface that the binding contracts do not define. The MVP reaches external state through the standard-service slots above; typed cross-family bindings arrive when that realization is specified as its own reviewed contract. This proposal does not invent it.</p><h2 id="lifecycle-risks" tabindex="-1">Lifecycle risks <a class="header-anchor" href="#lifecycle-risks" aria-label="Permalink to &quot;Lifecycle risks&quot;">​</a></h2><p>A host must be able to start instances of a revision for as long as it exists: it resolves and verifies the digest before any mutation, and a registry that later drops the digest must not break a serving revision — retention is the host&#39;s obligation from acceptance onward. Deleting a revision still weighted by a traffic resource must fail with <code>dependency_in_use</code>. A REQUIRED external-service slot a host cannot satisfy is refused at plan time with <code>unsupported_capability</code>, and an unsatisfied slot makes the resource not Ready. Import must reproduce the exact snapshot, digest included.</p><h2 id="prior-art" tabindex="-1">Prior art <a class="header-anchor" href="#prior-art" aria-label="Permalink to &quot;Prior art&quot;">​</a></h2><p>The immutable revision of a proven serverless container platform: image digest, environment, resources, concurrency, and instance bounds frozen together. The withdrawn v1alpha2 <code>ContainerService</code> candidate, whose mutable service document and open value tokens this Form replaces with digest-pinned revisions.</p>',22)])])}const p=a(r,[["render",n]]);export{u as __pageData,p as default};
